import pandas as pd
from collections import Counter
from typing import List, Tuple

from solver import Algorithm


class Evolved(Algorithm):
    """Optimize row serialization with bounded global column-chain candidates."""

    def __init__(self, df: pd.DataFrame = None):
        """Store the dataframe and initialize shape metadata."""
        self.df = df
        self.num_rows = 0
        self.num_cols = 0

    @staticmethod
    def _text(value) -> str:
        """Serialize one cell, mapping scalar missing values to empty text."""
        try:
            missing = pd.isna(value)
            if isinstance(missing, bool) and missing:
                return ""
        except Exception:
            pass
        return str(value)

    @staticmethod
    def _lcp(left: str, right: str) -> int:
        """Return exact common-prefix length using binary-search slicing."""
        limit = min(len(left), len(right))
        if not limit or left[0] != right[0]:
            return 0

        low, high = 1, limit
        while low < high:
            middle = (low + high + 1) // 2
            if left[:middle] == right[:middle]:
                low = middle
            else:
                high = middle - 1
        return low

    @classmethod
    def _reuse(cls, strings: List[str]) -> int:
        """Compute exact character-Trie reuse from sorted adjacent strings."""
        if len(strings) < 2:
            return 0

        ordered = sorted(strings)
        total = 0
        previous = ordered[0]

        for current in ordered[1:]:
            if current == previous:
                total += len(current)
            else:
                total += cls._lcp(previous, current)
            previous = current

        return total

    @staticmethod
    def _merge(columns, order, col_merge):
        """Keep requested merge groups contiguous while preserving all columns."""
        if not col_merge:
            return list(order)

        positions = {column: i for i, column in enumerate(order)}
        claimed = set()
        owners = {}

        for requested in col_merge:
            group = [
                column for column in order
                if column in requested and column not in claimed
            ]
            if not group:
                continue

            group.sort(key=positions.__getitem__)
            for column in group:
                owners[column] = group
                claimed.add(column)

        result = []
        emitted = set()

        for column in order:
            if column in emitted:
                continue

            group = owners.get(column)
            if group is None:
                result.append(column)
                emitted.add(column)
            else:
                result.extend(group)
                emitted.update(group)

        return result

    @classmethod
    def _normalize(cls, columns, integer_order, col_merge):
        """Convert an integer permutation into a complete merge-valid permutation."""
        proposed = [columns[i] for i in integer_order]
        merged = cls._merge(columns, proposed, col_merge)
        lookup = {column: i for i, column in enumerate(columns)}
        return [lookup[column] for column in merged]

    @staticmethod
    def _serialize(text, orders):
        """Serialize every row using its supplied row-specific column order."""
        return [
            "".join(text[row][column] for column in orders[row])
            for row in range(len(orders))
        ]

    def _global_candidates(self, text, columns, col_merge):
        """Build frequency-ranked and directed repeated-prefix chain layouts."""
        rows = len(text)
        width = len(columns)

        masses = []
        cardinalities = []

        for column in range(width):
            counts = Counter(text[row][column] for row in range(rows))
            masses.append(sum(
                len(value) * count * (count - 1)
                for value, count in counts.items()
            ))
            cardinalities.append(len(counts))

        ranked = sorted(
            range(width),
            key=lambda column: (
                -masses[column],
                cardinalities[column],
                column,
            ),
        )

        frequency_order = self._normalize(columns, ranked, col_merge)

        examined = ranked[:min(28, width)]
        arcs = []

        for left in examined:
            for right in examined:
                if left == right:
                    continue

                counts = Counter(
                    text[row][left] + text[row][right]
                    for row in range(rows)
                )
                mass = sum(
                    len(value) * count * (count - 1)
                    for value, count in counts.items()
                )

                if mass:
                    arcs.append((-mass, left, right))

        arcs.sort()

        outgoing = {}
        incoming = {}
        successor = {}
        predecessor = {}

        def creates_cycle(source, target):
            """Return whether adding source-to-target closes a directed path."""
            node = source
            while node in successor:
                node = successor[node]
                if node == target:
                    return True
            return node == target

        for _, source, target in arcs:
            if source in outgoing or target in incoming:
                continue
            if creates_cycle(source, target):
                continue

            outgoing[source] = target
            incoming[target] = source
            successor[source] = target
            predecessor[target] = source

            if len(outgoing) >= width - 1:
                break

        paths = []
        used = set()

        starts = sorted(
            (node for node in outgoing if node not in predecessor),
            key=lambda node: (-masses[node], node),
        )

        for start in starts:
            path = []
            node = start
            while node not in used:
                path.append(node)
                used.add(node)
                if node not in successor:
                    break
                node = successor[node]
            paths.append(path)

        for column in ranked:
            if column not in used:
                paths.append([column])

        chain_order = []
        for path in paths:
            chain_order.extend(path)

        chain_order = self._normalize(columns, chain_order, col_merge)
        return [frequency_order, chain_order], ranked

    def _prototype_candidate(self, text, columns, col_merge, base_order):
        """Construct bounded row-specific orders by matching rows to prototypes."""
        rows = len(text)
        width = len(columns)
        fallback = self._normalize(columns, base_order, col_merge)
        result = [fallback[:] for _ in range(rows)]

        if rows < 2 or width < 2:
            return result

        sample_rows = list(range(min(rows, 256)))
        active = base_order[:min(width, 32)]

        def make_string(row, order):
            """Serialize one sampled row through a candidate order."""
            return "".join(text[row][column] for column in order)

        initial = [make_string(row, active) for row in sample_rows]
        anchor_positions = [0]
        prototypes = [initial[0]]

        while len(anchor_positions) < min(4, len(sample_rows)):
            best_position = -1
            best_distance = -1

            for position, value in enumerate(initial):
                if position in anchor_positions:
                    continue

                nearest = max(self._lcp(value, prototype) for prototype in prototypes)
                distance = len(value) - nearest

                if distance > best_distance:
                    best_distance = distance
                    best_position = position

            if best_position < 0:
                break

            anchor_positions.append(best_position)
            prototypes.append(initial[best_position])

        def assign(strings, prototypes):
            """Assign each string to the prototype with greatest prefix match."""
            result = []
            for value in strings:
                scores = [self._lcp(value, prototype) for prototype in prototypes]
                result.append(max(range(len(scores)), key=scores.__getitem__))
            return result

        assignments = assign(initial, prototypes)

        for position, row in enumerate(sample_rows):
            prototype = prototypes[assignments[position]]
            remaining = list(active)
            chosen = []
            cursor = 0

            while remaining:
                best_column = remaining[0]
                best_score = -1

                for column in remaining:
                    score = self._lcp(text[row][column], prototype[cursor:])
                    if score > best_score:
                        best_score = score
                        best_column = column

                chosen.append(best_column)
                cursor += len(text[row][best_column])
                remaining.remove(best_column)

            tail = [column for column in base_order if column not in chosen]
            result[row] = self._normalize(
                columns,
                chosen + tail,
                col_merge,
            )

        return result

    def reorder(
        self,
        df: pd.DataFrame,
        early_stop: int = 0,
        row_stop: int = None,
        col_stop: int = None,
        col_merge=[],
        one_way_dep=[],
        distinct_value_threshold=0.8,
        parallel=True,
    ) -> Tuple[pd.DataFrame, List[List[str]]]:
        """Select the best bounded candidate by exact serialized Trie reuse."""
        self.df = df
        self.num_rows, self.num_cols = df.shape

        rows, width = df.shape
        columns = list(df.columns)

        if rows == 0 or width == 0:
            return df.copy(), [[] for _ in range(rows)]

        raw = df.to_numpy(dtype=object, copy=True)
        text = [
            [self._text(raw[row, column]) for column in range(width)]
            for row in range(rows)
        ]

        global_candidates, base_order = self._global_candidates(
            text,
            columns,
            col_merge,
        )

        candidates = []

        for order in global_candidates:
            orders = [order[:] for _ in range(rows)]
            serialized = self._serialize(text, orders)
            candidates.append((
                self._reuse(serialized),
                orders,
                serialized,
            ))

        prototype_orders = self._prototype_candidate(
            text,
            columns,
            col_merge,
            base_order,
        )
        prototype_serialized = self._serialize(text, prototype_orders)
        candidates.append((
            self._reuse(prototype_serialized),
            prototype_orders,
            prototype_serialized,
        ))

        _, best_orders, best_serialized = max(
            candidates,
            key=lambda item: item[0],
        )

        row_order = sorted(
            range(rows),
            key=lambda row: best_serialized[row],
        )

        output = [
            [raw[row, column] for column in best_orders[row]]
            for row in row_order
        ]
        orderings = [
            [columns[column] for column in best_orders[row]]
            for row in row_order
        ]

        result = pd.DataFrame(
            output,
            columns=columns,
            index=df.index.take(row_order),
            dtype=object,
        )
        return result, orderings

